style.css:
@-moz-document domain("youtube.com") {
/* General background and text */
    body, ytd-app {
        background-color: #0a0a0a !important;
        color: #e0f7ff !important;
        font-family: 'Kanit', sans-serif !important;
    }

    /* Top bar */
    ytd-masthead, #container.ytd-masthead {
        background-color: #1c3aa9 !important;
    }

    /* Sidebar and video grid background */
    #guide, ytd-mini-guide-renderer, ytd-rich-grid-renderer {
        background-color: #001a33 !important;
    }

    /* Links and buttons */
    a, button, yt-icon-button {
        color: #ffd700 !important;
    }

    /* Progress bar colors */
    .ytp-play-progress {
        background-color: #ffd700 !important;
    }

    .ytp-load-progress,
    .ytp-progress-bar {
        background-color: #1c3aa9 !important;
    }

    /* Shadowmilk character on progress bar */
    .ytp-scrubber-button::after {
        content: '';
        display: block;
        width: 40px;
        height: 40px;
        background-image: url("https://i.postimg.cc/brqQjQZd/430859.png");
        background-size: contain;
        background-repeat: no-repeat;
        position: absolute;
        top: -30px;
        left: -12px;
        z-index: 10;
        pointer-events: none;
    }

    .ytp-scrubber-button {
        background-color: transparent !important;
    }
}
